package standalone_test

// Parity oracle (added by tools/parity overlay, never committed upstream):
// the official go-sdk MCP client, an implementation independent of the
// agent, drives OPUTE_STANDALONE_BINARY through the 2026-07-28 handshake.

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type parityBearer struct{ token string }

func (b parityBearer) RoundTrip(r *http.Request) (*http.Response, error) {
	r = r.Clone(r.Context())
	r.Header.Set("Authorization", "Bearer "+b.token)
	return http.DefaultTransport.RoundTrip(r)
}

func TestParityRealClientModernHandshake(t *testing.T) {
	binary := os.Getenv("OPUTE_STANDALONE_BINARY")
	if binary == "" {
		t.Skip("OPUTE_STANDALONE_BINARY not set")
	}

    agentID := os.Getenv("PARITY_AGENT_ID")
    token := os.Getenv("PARITY_BEARER_TOKEN")
    sandbox := os.Getenv("PARITY_SANDBOX")
    if agentID == "" || token == "" || sandbox == "" {
        t.Fatal("isolated parity identity, token and sandbox are required")
    }
	port := freeStandalonePort(t)
	ctx, cancel := context.WithTimeout(context.Background(), standaloneProcessTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, binary, "--mode=standalone")
	cmd.Env = standaloneCleanEnv(
		"OPUTE_REMOTE_AGENT_ID="+agentID,
		"OPUTE_AGENT_MODE=standalone",
		"OPUTE_INFRA_PROVIDER_ID=incus",

        "HOME="+sandbox+"/home",
        "XDG_CONFIG_HOME="+sandbox+"/xdg",
        "PATH="+sandbox+"/shims:/usr/bin:/bin",
        "OPUTE_HOST_AGENT_INSTANCE_ROOT="+sandbox+"/instance",
        "OPUTE_INCUS_BINARY_PATH="+sandbox+"/shims/incus",
		"OPUTE_STANDALONE_STATE_DIR="+t.TempDir(),
		"HOST_MCP_BIND_HOST=127.0.0.1",
		fmt.Sprintf("HOST_MCP_PORT=%d", port),
		"MCP_AUTH_TOKEN="+token,
	)
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	defer func() {
		_ = cmd.Process.Signal(os.Interrupt)
		_, _ = cmd.Process.Wait()
	}()
	base := fmt.Sprintf("http://127.0.0.1:%d", port)
	deadline := time.Now().Add(standaloneReadyTimeout)
	for {
		res, err := http.Get(base + "/health")
		if err == nil {
			res.Body.Close()
			if res.StatusCode == http.StatusOK {
				break
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("agent not ready: %v", err)
		}
		time.Sleep(100 * time.Millisecond)
	}

	client := mcp.NewClient(&mcp.Implementation{Name: "parity-real-client", Version: "1"}, nil)
	transport := &mcp.StreamableClientTransport{
		Endpoint:   base + "/mcp",
		HTTPClient: &http.Client{Transport: parityBearer{token: token}},
	}
	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		t.Fatalf("connect: %v", err)
	}
	defer session.Close()
	if info := session.InitializeResult(); info == nil || info.ServerInfo == nil ||
		info.ServerInfo.Name != "host-agent" || info.ServerInfo.Version == "" {
		t.Fatalf("server info = %+v", info)
	}
	if _, err := session.ListTools(ctx, nil); err != nil {
		t.Fatalf("tools/list: %v", err)
	}
	if _, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "parity_no_such_tool", Arguments: map[string]any{}}); err == nil {
		t.Fatal("tools/call of an unknown tool succeeded")
	}

	// A client without the bearer token is refused.
	anonymous := mcp.NewClient(&mcp.Implementation{Name: "parity-anonymous", Version: "1"}, nil)
	if s, err := anonymous.Connect(ctx, &mcp.StreamableClientTransport{Endpoint: base + "/mcp"}, nil); err == nil {
		_ = s.Close()
		t.Fatal("unauthenticated client connected")
	}
}

package standalone_test

// Parity oracle (added by tools/parity overlay, never committed upstream):
// the official go-sdk client reads the published catalog and calls read-only
// capabilities against OPUTE_STANDALONE_BINARY (M3).

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestParityRealClientCatalogAndReadTools(t *testing.T) {
	binary := os.Getenv("OPUTE_STANDALONE_BINARY")
	if binary == "" {
		t.Skip("OPUTE_STANDALONE_BINARY not set")
	}

    agentID := os.Getenv("PARITY_AGENT_ID")
    token := os.Getenv("PARITY_BEARER_TOKEN")
    sandbox := os.Getenv("PARITY_SANDBOX")
    if agentID == "" || token == "" || sandbox == "" {
        t.Fatal("isolated parity identity, token and sandbox are required")
    }
	port := freeStandalonePort(t)
	ctx, cancel := context.WithTimeout(context.Background(), standaloneProcessTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, binary, "--mode=standalone")
	cmd.Env = standaloneCleanEnv(
		"OPUTE_REMOTE_AGENT_ID="+agentID,
		"OPUTE_AGENT_MODE=standalone",
		"OPUTE_INFRA_PROVIDER_ID=incus",

        "HOME="+sandbox+"/home",
        "XDG_CONFIG_HOME="+sandbox+"/xdg",
        "PATH="+sandbox+"/shims:/usr/bin:/bin",
        "OPUTE_HOST_AGENT_INSTANCE_ROOT="+sandbox+"/instance",
        "OPUTE_INCUS_BINARY_PATH="+sandbox+"/shims/incus",
		"OPUTE_STANDALONE_STATE_DIR="+t.TempDir(),
		"HOST_MCP_BIND_HOST=127.0.0.1",
		fmt.Sprintf("HOST_MCP_PORT=%d", port),
		"MCP_AUTH_TOKEN="+token,
	)
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	defer func() {
		_ = cmd.Process.Signal(os.Interrupt)
		_, _ = cmd.Process.Wait()
	}()
	base := fmt.Sprintf("http://127.0.0.1:%d", port)
	deadline := time.Now().Add(standaloneReadyTimeout)
	for {
		res, err := http.Get(base + "/health")
		if err == nil {
			res.Body.Close()
			if res.StatusCode == http.StatusOK {
				break
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("agent not ready: %v", err)
		}
		time.Sleep(100 * time.Millisecond)
	}
	client := mcp.NewClient(&mcp.Implementation{Name: "parity-catalog-client", Version: "1"}, nil)
	session, err := client.Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint:   base + "/mcp",
		HTTPClient: &http.Client{Transport: parityBearer{token: token}},
	}, nil)
	if err != nil {
		t.Fatalf("connect: %v", err)
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("tools/list: %v", err)
	}
	if len(tools.Tools) != 142 {
		t.Fatalf("standalone catalog has %d tools, want 142", len(tools.Tools))
	}
	revision := ""
	for _, tool := range tools.Tools {
		if tool.InputSchema == nil {
			t.Fatalf("%s has no input schema", tool.Name)
		}
		rev, _ := tool.Meta["catalogRevision"].(string)
		if !strings.HasPrefix(rev, "sha256:") || (revision != "" && rev != revision) {
			t.Fatalf("%s catalog revision %q", tool.Name, rev)
		}
		revision = rev
		if _, ok := tool.Meta["capability"].(map[string]any); !ok {
			t.Fatalf("%s has no capability descriptor", tool.Name)
		}
	}

	catalog, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "get_capability_catalog", Arguments: map[string]any{}})
	if err != nil || catalog.IsError {
		t.Fatalf("get_capability_catalog: %v %+v", err, catalog)
	}
	snapshot, _ := catalog.StructuredContent.(map[string]any)
	if snapshot["catalogRevision"] != revision {
		t.Fatalf("snapshot revision %v, tools/list revision %s", snapshot["catalogRevision"], revision)
	}

	info, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "get_host_info", Arguments: map[string]any{}})
	if err != nil || info.IsError {
		t.Fatalf("get_host_info: %v %+v", err, info)
	}
	host, _ := info.StructuredContent.(map[string]any)
	if host["uri"] != "host:local:"+agentID || host["providerId"] != "incus" {
		t.Fatalf("get_host_info = %v", host)
	}

	bad, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "list_vms", Arguments: map[string]any{"fast": "yes"}})
	if err != nil || !bad.IsError {
		t.Fatalf("list_vms with a string flag: %v %+v", err, bad)
	}
	denied, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "create_vm", Arguments: map[string]any{"name": "x"}})
	if err != nil || !denied.IsError {
		t.Fatalf("create_vm with mutations disabled: %v %+v", err, denied)
	}

    // The same official MCP session must remain usable after both failures.
    after, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "get_host_info", Arguments: map[string]any{}})
    if err != nil || after.IsError {
        t.Fatalf("get_host_info after rejection: %v %+v", err, after)
    }
    again, _ := after.StructuredContent.(map[string]any)
    if again["uri"] != host["uri"] || again["providerId"] != host["providerId"] {
        t.Fatalf("identity changed after rejection: %v", again)
    }
    afterCatalog, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "get_capability_catalog", Arguments: map[string]any{}})
    if err != nil || afterCatalog.IsError {
        t.Fatalf("catalog after rejection: %v %+v", err, afterCatalog)
    }
    afterSnapshot, _ := afterCatalog.StructuredContent.(map[string]any)
    if afterSnapshot["catalogRevision"] != revision {
        t.Fatalf("catalog revision changed after rejection: %v", afterSnapshot)
    }
}
